import { notFound } from "next/navigation";import Link from "next/link";import { categories,categoryLabel } from "@/lib/types";import { seedFestivals } from "@/lib/festivals";import { FestivalCard } from "@/components/festival-card";export default async function Page({params}:{params:Promise<{slug:string}>}){const {slug}=await params;if(!categories.includes(slug as typeof categories[number]))notFound();const items=seedFestivals.filter(x=>x.category===slug);return <main className="wrap section"><Link href="/" className="muted">← All festivals</Link><h1>{categoryLabel(slug as typeof categories[number])} festivals</h1><p className="muted">Experiences you can join, taste, make, and share.</p><div className="grid">{items.map(x=><FestivalCard key={x.id} festival={x}/>)}</div></main>}
